import {validate,migrate} from './core.mjs?v=4';
const encode=new TextEncoder(),decode=new TextDecoder();
const b64=b=>btoa(Array.from(new Uint8Array(b),x=>String.fromCharCode(x)).join(''));
const un64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
let dbPromise;
function db(){return dbPromise??=new Promise((resolve,reject)=>{const r=indexedDB.open('orbe-private-vaults',2);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains('users'))d.createObjectStore('users',{keyPath:'id'});if(!d.objectStoreNames.contains('sessions'))d.createObjectStore('sessions',{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('Não foi possível acessar o armazenamento deste navegador.'))})}
async function read(method,arg){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('users','readonly'),r=t.objectStore('users')[method](arg);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function readSession(method,arg){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('sessions','readonly'),r=t.objectStore('sessions')[method](arg);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function writeSession(record){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('sessions','readwrite');t.objectStore('sessions').put(record);t.oncomplete=()=>resolve();t.onerror=()=>reject(t.error)})}
async function clearSession(){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('sessions','readwrite');t.objectStore('sessions').clear();t.oncomplete=()=>resolve();t.onerror=()=>reject(t.error)})}
async function write(record){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('users','readwrite');t.objectStore('users').put(record);t.oncomplete=()=>resolve();t.onerror=()=>reject(Error('Não foi possível salvar. Exporte um backup e verifique o espaço do navegador.'));t.onabort=()=>reject(Error('O salvamento foi interrompido.'))})}
async function key(password,salt){const k=await crypto.subtle.importKey('raw',encode.encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt:un64(salt),iterations:310000,hash:'SHA-256'},k,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function seal(data,k){const iv=crypto.getRandomValues(new Uint8Array(12));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},k,encode.encode(JSON.stringify(data)));return {iv:b64(iv),cipher:b64(cipher)}}
async function open(record,k){return JSON.parse(decode.decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:un64(record.iv)},k,un64(record.cipher))))}
export const users=async()=>(await read('getAll')).map(({id,name})=>({id,name}));
export async function rename(id,name){const record=await read('get',id);if(!record)throw Error('Usuário não encontrado.');const next={...record,name:name.trim()};if(!next.name)throw Error('Informe um nome.');await write(next);return {id:next.id,name:next.name}}
export async function remove(id){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('users','readwrite');const r=t.objectStore('users').delete(id);r.onerror=()=>reject(r.error);t.oncomplete=()=>resolve()})}
export async function create(name,password,data){if(password.length<8)throw Error('Use uma senha com pelo menos 8 caracteres.');const salt=b64(crypto.getRandomValues(new Uint8Array(16)));const k=await key(password,salt);const normalized=migrate(data);validate(normalized);const record={id:crypto.randomUUID(),name,salt,revision:0,...await seal(normalized,k)};await write(record);return {record,key:k,data:normalized}}
export async function unlock(id,password){const record=await read('get',id);if(!record)throw Error('Usuário não encontrado.');const k=await key(password,record.salt);let data;try{data=migrate(await open(record,k))}catch{throw Error('Senha incorreta ou cofre danificado.')}validate(data);return {record,key:k,data}}
export async function changePassword(session,currentPassword,nextPassword){if(nextPassword.length<8)throw Error('Use uma senha com pelo menos 8 caracteres.');const currentKey=await key(currentPassword,session.record.salt);let data;try{data=migrate(await open(session.record,currentKey))}catch{throw Error('A senha atual está incorreta.')}validate(data);const salt=b64(crypto.getRandomValues(new Uint8Array(16)));const nextKey=await key(nextPassword,salt);const record={...session.record,salt,revision:session.record.revision+1,...await seal(data,nextKey)};await write(record);return {record,key:nextKey,data}}
export async function remember(session){await writeSession({id:'current',userId:session.record.id,key:session.key})}
export async function forget(){await clearSession()}
export async function resume(){const saved=await readSession('get','current');if(!saved?.userId||!saved?.key)return null;const record=await read('get',saved.userId);if(!record){await clearSession();return null}try{const data=migrate(await open(record,saved.key));validate(data);return {record,key:saved.key,data}}catch{await clearSession();return null}}
export async function save(session,data){const normalized=migrate(data);validate(normalized);const work=async()=>{const current=await read('get',session.record.id);if(current.revision!==session.record.revision)throw Error('Este cofre mudou em outra aba. Saia e entre novamente antes de editar.');const next={...session.record,revision:session.record.revision+1,...await seal(normalized,session.key)};await write(next);session.record=next;session.data=normalized};if(navigator.locks)return navigator.locks.request('orbe-save-'+session.record.id,work);return work()}
export function backup(session){return JSON.stringify({format:'orbe-encrypted-v1',exportedAt:new Date().toISOString(),user:session.record},null,2)}
export async function readBackup(text,password){const b=JSON.parse(text);if(b.format!=='orbe-encrypted-v1'||!b.user?.salt||!b.user?.cipher)throw Error('Escolha um backup .orbe válido.');const k=await key(password,b.user.salt);let data;try{data=migrate(await open(b.user,k))}catch{throw Error('A senha do backup está incorreta ou o arquivo está danificado.')}validate(data);return data}
